 if (Math.random() < 0.5) {
 return;
 } else {
 throw new Error();
 }

}
```
Examples of **correct** code for this rule, because of JavaScript function and variable hoisting:

```
/*eslint no-unreachable: "error"*/
function foo() {
 return bar();
 function bar() {
 return 1;
 }
}
function bar() {
 return x;
 var x;
}
switch (foo) {
 case 1:
 break;
 var x;
}
```
Examples of additional **incorrect** code for this rule:

```
/*eslint no-unreachable: "error"*/
class C extends B {
 // unreachable
 constructor() {
 return {};
 }
}
```
Examples of additional **correct** code for this rule:

```
/*eslint no-unreachable: "error"*/
class D extends B {
 #x;
 #y = 1;
 a;
 b = 1;
 constructor() {
 super();
 }
}
class E extends B {
 #x;
 #y = 1;
 a;
 b = 1;
 // implicit constructor always calls `super()`
}
class F extends B {
 static #x;
 static #y = 1;
 static a;
 static b = 1;
 constructor() {
 return {};
 }
}
```

