 tests := []struct{
 desc string
 data *anypb.Any
 }{
 {
 desc: "my test case",
 // Creating values directly within table driven test cases.
 data: mustMarshalAny(t, mypb.Object{}),
 },
 // ...
 }
 // ...
}
