// Bad:
switch bad := db.TransactionStatus(); bad {
case db.TransactionStarting,
 db.TransactionActive,
 db.TransactionWaiting:
 // ...
case db.TransactionCommitted,
 db.NoTransaction:
 // ...
default:
 // ...
}
```
