 "Certificates": {
 "Install": [
 "/usr/local/share/ca-certificates/aspnet/https.crt"
 ]
 }
 }
}
EOF
```
Note: Ubuntu 21.10 Firefox comes as a snap package and the installation folder is `/snap/firefox/current/usr/lib/firefox`.

