 ControllerContext.MyDisplayRouteInfo(id);
 // GET: api/TodoItems1
 [HttpGet]
 public IActionResult GetTodoItems() =>
 ControllerContext.MyDisplayRouteInfo();
 [EnableCors("MyPolicy")]
 [HttpGet("{action}")]
 public IActionResult GetTodoItems2() =>
 ControllerContext.MyDisplayRouteInfo();
 // Delete: api/TodoItems1/MyDelete2/5
 [EnableCors("MyPolicy")]
