Source: Aspnet Core Security > ASP.NET Core security features > Create a Web app with authentication > Configure Identity services

### Configure Identity services

Services are added in `ConfigureServices`. The typical pattern is to call all the `Add{Service}` methods, and then call all the `services.Configure{Service}` methods.

```
public void ConfigureServices(IServiceCollection services)
{
 services.AddDbContext<ApplicationDbContext>(options =>
 // options.UseSqlite(
 options.UseSqlServer(
 Configuration.GetConnectionString("DefaultConnection")));
 services.AddDefaultIdentity<IdentityUser>(options => options.SignIn.RequireConfirmedAccount = true)
 .AddEntityFrameworkStores<ApplicationDbContext>();
 services.AddRazorPages();
 services.Configure<IdentityOptions>(options =>
 {
 // Password settings.
 options.Password.RequireDigit = true;
 options.Password.RequireLowercase = true;
 options.Password.RequireNonAlphanumeric = true;
 options.Password.RequireUppercase = true;
 options.Password.RequiredLength = 6;
 options.Password.RequiredUniqueChars = 1;
 // Lockout settings.
 options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(5);
 options.Lockout.MaxFailedAccessAttempts = 5;
 options.Lockout.AllowedForNewUsers = true;
 // User settings.
 options.User.AllowedUserNameCharacters =
 "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._@+";
 options.User.RequireUniqueEmail = false;
 });
 services.ConfigureApplicationCookie(options =>
 {
 // Cookie settings
 options.Cookie.HttpOnly = true;
 options.ExpireTimeSpan = TimeSpan.FromMinutes(5);
 options.LoginPath = "/Identity/Account/Login";
 options.AccessDeniedPath = "/Identity/Account/AccessDenied";
 options.SlidingExpiration = true;
 });
}
```
