 return string.equals("");
 }
 // @BeforeTemplate is missing
 boolean before2(String string) {
 return string.length() == 0;
 }
 @AfterTemplate
 @AlsoNegation
 boolean after(String string) {
 return string.isEmpty();
 }
}
```
