Source: Cpp Core Guidelines > <a name="s-interfaces"></a>I: Interfaces > <a name="ri-explicit"></a>I.1: Make interfaces explicit > <a name="ri-pimpl"></a>I.27: For stable library ABI, consider the Pimpl idiom > Reason > Example

##### Example

interface (widget.h)

 class widget {
 class impl;
 std::unique_ptr<impl> pimpl;
 public:
 void draw(); // public API that will be forwarded to the implementation
 widget(int); // defined in the implementation file
 ~widget(); // defined in the implementation file, where impl is a complete type
 widget(widget&&) noexcept; // defined in the implementation file
 widget(const widget&) = delete;
 widget& operator=(widget&&) noexcept; // defined in the implementation file
 widget& operator=(const widget&) = delete;
 };

implementation (widget.cpp)

 class widget::impl {
 int n; // private data
 public:
 void draw(const widget& w) { /* ... */ }
 impl(int n) : n(n) {}
 };
 void widget::draw() { pimpl->draw(*this); }
 widget::widget(int n) : pimpl{std::make_unique<impl>(n)} {}
 widget::widget(widget&&) noexcept = default;
 widget::~widget() = default;
 widget& widget::operator=(widget&&) noexcept = default;

