##### Example

 class My_class {
 int x = 0;
 // ...

 void f()
 {
 int i = 0;
 // ...

 auto lambda = [=] { use(i, x); }; // BAD: "looks like" copy/value capture

 x = 42;
 lambda(); // calls use(0, 42);
 x = 43;
 lambda(); // calls use(0, 43);

 // ...

 auto lambda2 = [i, this] { use(i, x); }; // ok, most explicit and least confusing

 // ...
 }
 };

