 };

 bool operator==(const Bundle& a, const Bundle& b)
 {
 return a.name == b.name && a.vr == b.vr;
 }

 Bundle b1 { "my bundle", {r1, r2, r3}};
 Bundle b2 = b1;
 if (!(b1 == b2)) error("impossible!");
