 class Vector1 {
 public:
 // sets the representation to {nullptr, nullptr, nullptr}; doesn't throw
 Vector1() noexcept {}
 Vector1(int n) :elem{new T[n]}, space{elem + n}, last{elem} {}
 // ...
 private:
