Source: Cpp Core Guidelines > <a name="s-class"></a>C: Classes and class hierarchies > <a name="ss-copy"></a>C.copy: Copy and move > <a name="rc-copy-semantic"></a>C.61: A copy operation should copy > Reason > Example

##### Example

 class X { // OK: value semantics
 public:
 X();
 X(const X&); // copy X
 void modify(); // change the value of X
 // ...
 ~X() { delete[] p; }
 private:
 T* p;
 int sz;
 };

 bool operator==(const X& a, const X& b)
 {
 return a.sz == b.sz && equal(a.p, a.p + a.sz, b.p, b.p + b.sz);
 }

 X::X(const X& a)
 :p{new T[a.sz]}, sz{a.sz}
 {
 copy(a.p, a.p + sz, p);
 }

 X x;
 X y = x;
 if (x != y) throw Bad{};
 x.modify();
 if (x == y) throw Bad{}; // assume value semantics

