 X::X(const X& a)
 :p{new T[a.sz]}, sz{a.sz}
 {
 copy(a.p, a.p + sz, p);
 }

 X x;
 X y = x;
 if (x != y) throw Bad{};
 x.modify();
 if (x == y) throw Bad{}; // assume value semantics

