Source: Cpp Core Guidelines > <a name="s-class"></a>C: Classes and class hierarchies > C.hierclass: Designing classes in a hierarchy: > <a name="rh-using"></a>C.138: Create an overload set for a derived class and its bases with `using` > Reason > Example, bad

##### Example, bad

 #include <iostream>
 class B {
 public:
 virtual int f(int i) { std::cout << "f(int): "; return i; }
 virtual double f(double d) { std::cout << "f(double): "; return d; }
 virtual ~B() = default;
 };
 class D: public B {
 public:
 int f(int i) override { std::cout << "f(int): "; return i + 1; }
 };
 int main()
 {
 D d;
 std::cout << d.f(2) << '\n'; // prints "f(int): 3"
 std::cout << d.f(2.3) << '\n'; // prints "f(int): 3"
 }

