Source: Cpp Core Guidelines > <a name="s-concurrency"></a>CP: Concurrency and parallelism > <a name="sscp-mess"></a>CP.mess: Message passing > <a name="rconc-async"></a>CP.61: Use `async()` to spawn concurrent tasks > Reason > Example

##### Example

 int read_value(const std::string& filename)
 {
 std::ifstream in(filename);
 in.exceptions(std::ifstream::failbit);
 int value;
 in >> value;
 return value;
 }

 void async_example()
 {
 try {
 std::future<int> f1 = std::async(read_value, "v1.txt");
 std::future<int> f2 = std::async(read_value, "v2.txt");
 std::cout << f1.get() + f2.get() << '\n';
 } catch (const std::ios_base::failure& fail) {
 // handle exception here
 }
 }

