 void async_example()
 {
 try {
 std::future<int> f1 = std::async(read_value, "v1.txt");
 std::future<int> f2 = std::async(read_value, "v2.txt");
 std::cout << f1.get() + f2.get() << '\n';
 } catch (const std::ios_base::failure& fail) {
 // handle exception here
 }
 }

