 // axiom(T a, T b) { a + b == b + a; a - a == 0; a * (b + c) == a * b + a * c; /*...*/ }
 concept Number = requires(T a, T b) {
 { a + b } -> convertible_to<T>;
 { a - b } -> convertible_to<T>;
 { a * b } -> convertible_to<T>;
 { a / b } -> convertible_to<T>;
