Source: Cpp Core Guidelines > <a name="s-not"></a>NR: Non-Rules and myths > <a name="rnr-top"></a>NR.1: Don't insist that all declarations should be at the top of a function > <a name="rnr-two-phase-init"></a>NR.5: Don't use two-phase initialization > Reason > Example, bad

##### Example, bad

 // Old conventional style: many problems

 class Picture
 {
 int mx;
 int my;
 int * data;
 public:
 // main problem: constructor does not fully construct
 Picture(int x, int y)
 {
 mx = x; // also bad: assignment in constructor body
 // rather than in member initializer
 my = y;
 data = nullptr; // also bad: constant initialization in constructor
 // rather than in member initializer
 }

 ~Picture()
 {
 Cleanup();
 }

 // ...

 // bad: two-phase initialization
 bool Init()
 {
 // invariant checks
 if (mx <= 0 || my <= 0) {
 return false;
 }
 if (data) {
 return false;
 }
 data = (int*) malloc(mx*my*sizeof(int)); // also bad: owning raw * and malloc
 return data != nullptr;
 }

 // also bad: no reason to make cleanup a separate function
 void Cleanup()
 {
 if (data) free(data);
 data = nullptr;
 }
 };

 Picture picture(100, 0); // not ready-to-use picture here
 // this will fail..
 if (!picture.Init()) {
 puts("Error, invalid picture");
 }
 // now have an invalid picture object instance.

