Source: Cpp Core Guidelines > <a name="s-not"></a>NR: Non-Rules and myths > <a name="rnr-top"></a>NR.1: Don't insist that all declarations should be at the top of a function > <a name="rnr-two-phase-init"></a>NR.5: Don't use two-phase initialization > Reason > Example, good

##### Example, good

 class Picture
 {
 int mx;
 int my;
 vector<int> data;

 static int check_size(int size)
 {
 // invariant check
 Expects(size > 0);
 return size;
 }

 public:
 // even better would be a class for a 2D Size as one single parameter
 Picture(int x, int y)
 : mx(check_size(x))
 , my(check_size(y))
 // now we know x and y have a valid size
 , data(mx * my) // will throw std::bad_alloc on error
 {
 // picture is ready-to-use
 }

 // compiler generated dtor does the job. (also see C.21)

 // ...
 };

 Picture picture1(100, 100);
 // picture1 is ready-to-use here...

 // not a valid size for y,
 // default contract violation behavior will call std::terminate then
 Picture picture2(100, 0);
 // not reach here...

