Source: Clang Tidy Checks > modernize-loop-convert > Example

## Example

Original:

```c++
const int N = 5;
int arr[] = {1,2,3,4,5};
vector<int> v;
v.push_back(1);
v.push_back(2);
v.push_back(3);

// safe conversion
for (int i = 0; i < N; ++i)
 cout << arr[i];

// reasonable conversion
for (vector<int>::iterator it = v.begin(); it != v.end(); ++it)
 cout << *it;

// reasonable conversion
for (vector<int>::iterator it = begin(v); it != end(v); ++it)
 cout << *it;

// reasonable conversion
for (vector<int>::iterator it = std::begin(v); it != std::end(v); ++it)
 cout << *it;

// reasonable conversion
for (int i = 0; i < v.size(); ++i)
 cout << v[i];

// reasonable conversion
for (int i = 0; i < size(v); ++i)
 cout << v[i];
```

After applying the check with minimum confidence level set to
`reasonable` (default):

```c++
const int N = 5;
int arr[] = {1,2,3,4,5};
vector<int> v;
v.push_back(1);
v.push_back(2);
v.push_back(3);

// safe conversion
for (auto & elem : arr)
 cout << elem;

// reasonable conversion
for (auto & elem : v)
 cout << elem;

// reasonable conversion
for (auto & elem : v)
 cout << elem;
```

